func modelDataOutlineIcon(tint gfx.Color) gfx.Icon {
	return officialVectorIcon(officialMediumStroke, tint,
		officialIconPart{d: officialModelDataFill, fill: true},
		officialIconPart{d: officialModelDataStroke})
}

func agentPresetOutlineIcon(tint gfx.Color) gfx.Icon {
	parts := []officialIconPart{{d: officialAgentPresetFill, fill: true}}
	for _, d := range officialAgentPresetStrokes {
		parts = append(parts, officialIconPart{d: d})
	}
	return officialVectorIcon(officialMediumStroke, tint, parts...)
}

func personalizationOutlineIcon(tint gfx.Color) gfx.Icon {
	parts := make([]officialIconPart, 0, len(officialPersonalizationFills))
	for _, d := range officialPersonalizationFills {
		parts = append(parts, officialIconPart{d: d, fill: true})
	}
	return officialVectorIcon(0, tint, parts...)
}
